import os, json, time

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
lines = t.split('\n')

valid_lines = [l for l in lines if l.strip()]

# Count user messages
user_msgs = []
for i, line in enumerate(valid_lines):
    try:
        data = json.loads(line)
        if data.get('type') == 'message' and data.get('message', {}).get('role') == 'user':
            text = data.get('message', {}).get('content', [{}])[0].get('text', '')
            if text:
                user_msgs.append((i, text[:80]))
    except:
        pass

print(f"User messages found: {len(user_msgs)}")
for idx, text in user_msgs:
    print(f"  Line {idx}: {text}...")

# Check for any messages with demo data after the initial task
print("\n=== Checking all text content for demo patterns ===")
for i, line in enumerate(valid_lines):
    try:
        data = json.loads(line)
        msg_type = data.get('type', '')
        if msg_type != 'message':
            continue
        role = data.get('message', {}).get('role', '')
        if role not in ['user', 'assistant']:
            continue
        content = data.get('message', {}).get('content', [{}])[0].get('text', '')
        if 'Demo pair' in content or content.startswith('[') and ']' in content:
            print(f"Line {i}: {role} message with potential demo")
            print(content[:500])
    except:
        pass

